<?php
require_once __DIR__ . '/../includes/bootstrap.php';
require_role('programme_manager');
require_once __DIR__ . '/_management_suite_helpers.php';
$user=current_user();$conn=Database::getConnection();$managerId=(int)($user['id']??$user['user_id']??0);if($managerId<=0){http_response_code(403);exit('Invalid Programme Manager account.');}
$currentPage='outcomes';$pageTitle='Outcome & Impact Tracking';$flashes=render_flashes();$errors=[];$tableReady=pm_table_exists($conn,'programme_outcomes');$programmes=pm_suite_programmes($conn,$managerId);$cohorts=pm_suite_cohorts($conn,$managerId);

$types=['achievement'=>'Achievement','completion'=>'Programme completion','employment'=>'Employment outcome','other'=>'Other outcome'];$editing=['id'=>0,'programme_id'=>0,'cohort_id'=>0,'candidate_id'=>0,'outcome_type'=>'achievement','outcome_title'=>'','details'=>'','achieved_on'=>date('Y-m-d'),'verified'=>0,'verification_reference'=>''];
if($_SERVER['REQUEST_METHOD']==='POST'){if(!validate_csrf())$errors[]='Session validation failed. Refresh and try again.';elseif(!$tableReady)$errors[]='Import database/programme_management_suite.sql before recording outcomes.';else{$pid=(int)($_POST['programme_id']??0);$cid=(int)($_POST['cohort_id']??0);$candidate=(int)($_POST['candidate_id']??0);$type=(string)($_POST['outcome_type']??'achievement');$title=trim((string)($_POST['outcome_title']??''));$details=trim((string)($_POST['details']??''));$date=(string)($_POST['achieved_on']??'');$verified=isset($_POST['verified'])?1:0;$ref=trim((string)($_POST['verification_reference']??''));if(!pm_suite_valid_scope($conn,$pid,$cid,$managerId))$errors[]='Choose a programme/cohort within your assigned scope.';if(!isset($types[$type]))$errors[]='Choose a valid outcome type.';if($title===''||mb_strlen($title)>180)$errors[]='Enter an outcome title of up to 180 characters.';$d=DateTime::createFromFormat('!Y-m-d',$date);if(!$d||$d->format('Y-m-d')!==$date)$errors[]='Choose a valid achievement date.';if($candidate>0){$s=$conn->prepare('SELECT cp.user_id FROM cohort_participants cp JOIN cohorts c ON c.id=cp.cohort_id JOIN programmes p ON p.id=c.programme_id WHERE cp.user_id=? AND c.programme_id=? AND p.programme_manager_id=? AND (?=0 OR c.id=?) LIMIT 1');$ok=false;if($s){$s->bind_param('iiiii',$candidate,$pid,$managerId,$cid,$cid);$s->execute();$ok=(bool)$s->get_result()->fetch_assoc();$s->close();}if(!$ok)$errors[]='Choose a candidate participating in the selected programme/cohort.';}if($type==='employment'&&$verified&&$ref==='')$errors[]='Provide a verification reference for a verified employment outcome.';if(!$errors){$cv=$cid?:null;$candidateVal=$candidate?:null;$refVal=$ref?:null;$s=$conn->prepare('INSERT INTO programme_outcomes(programme_id,cohort_id,candidate_id,outcome_type,outcome_title,details,achieved_on,verified,verification_reference,recorded_by) VALUES(?,?,?,?,?,?,?,?,?,?)');if($s){$s->bind_param('iiissssisi',$pid,$cv,$candidateVal,$type,$title,$details,$date,$verified,$refVal,$managerId);if($s->execute()){$s->close();set_flash('success','Outcome recorded','The programme outcome has been saved.');safe_redirect('programme/outcomes.php');}$s->close();}$errors[]='The outcome could not be saved.';}}}
$outcomes=[];$stats=['records'=>0,'verified'=>0,'employment'=>0,'completions'=>0,'participants'=>0,'completed_candidates'=>0,'placements'=>0];
if($tableReady){$s=$conn->prepare("SELECT o.*,p.name programme_name,c.name cohort_name,TRIM(CONCAT(COALESCE(u.first_name,''),' ',COALESCE(u.last_name,''))) candidate_name FROM programme_outcomes o JOIN programmes p ON p.id=o.programme_id LEFT JOIN cohorts c ON c.id=o.cohort_id LEFT JOIN users u ON u.id=o.candidate_id WHERE p.programme_manager_id=? ORDER BY o.achieved_on DESC,o.id DESC");if($s){$s->bind_param('i',$managerId);$s->execute();$outcomes=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();}foreach($outcomes as $o){$stats['records']++;if((int)$o['verified'])$stats['verified']++;if($o['outcome_type']==='employment'&&(int)$o['verified'])$stats['employment']++;if($o['outcome_type']==='completion')$stats['completions']++;}}
$s=$conn->prepare("SELECT COUNT(DISTINCT CONCAT(c.id,':',cp.user_id)) participants,COUNT(DISTINCT CASE WHEN cp.status='completed' THEN CONCAT(c.id,':',cp.user_id) END) completed FROM cohorts c JOIN programmes p ON p.id=c.programme_id LEFT JOIN cohort_participants cp ON cp.cohort_id=c.id AND cp.status<>'withdrawn' WHERE p.programme_manager_id=?");if($s){$s->bind_param('i',$managerId);$s->execute();$r=$s->get_result()->fetch_assoc()?:[];$stats['participants']=(int)($r['participants']??0);$stats['completed_candidates']=(int)($r['completed']??0);$s->close();}$s=$conn->prepare("SELECT COUNT(*) n FROM placements pl JOIN programmes p ON p.id=pl.programme_id WHERE p.programme_manager_id=? AND pl.status IN ('placed','active','completed')");if($s){$s->bind_param('i',$managerId);$s->execute();$stats['placements']=(int)($s->get_result()->fetch_assoc()['n']??0);$s->close();}
$candidates=[];$s=$conn->prepare("SELECT DISTINCT cp.user_id id,TRIM(CONCAT(u.first_name,' ',u.last_name)) name,c.programme_id,c.id cohort_id,c.name cohort_name,p.name programme_name FROM cohort_participants cp JOIN cohorts c ON c.id=cp.cohort_id JOIN programmes p ON p.id=c.programme_id JOIN users u ON u.id=cp.user_id WHERE p.programme_manager_id=? AND cp.status<>'withdrawn' ORDER BY p.name,c.name,name");if($s){$s->bind_param('i',$managerId);$s->execute();$candidates=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=e($pageTitle)?> | Investhood IT</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><link rel="stylesheet" href="<?=url('css/styles.css')?>"><link rel="stylesheet" href="<?=url('css/programme_manager_enhancements.css')?>?v=20261026"><link rel="stylesheet" href="<?=url('css/programme_management_suite.css')?>?v=20261026"></head><body class="dashboard-page"><div class="dashboard"><?php require __DIR__.'/sidebar.php';?><main class="dashboard__main"><?php require __DIR__.'/navbar.php';?><div class="pm-suite"><?=$flashes?>

<section class="pm-suite-hero"><div><span class="pm-suite-eyebrow">Results &amp; accountability</span><h1>Programme Outcome &amp; Impact Tracking</h1><p>Capture achievements and completion milestones, review candidate progression, and record employment outcomes only when supporting verification is available.</p></div></section><?php foreach($errors as $error):?><div class="pm-suite-alert"><?=e($error)?></div><?php endforeach;?><?php if(!$tableReady):?><div class="pm-suite-notice">Import <code>database/programme_management_suite.sql</code> into the active database to enable outcome records.</div><?php endif;?>
<section class="pm-suite-kpis"><article class="pm-suite-kpi"><small>Participants</small><strong><?=number_format($stats['participants'])?></strong><span>Non-withdrawn cohort participants</span></article><article class="pm-suite-kpi"><small>Programme completions</small><strong><?=number_format($stats['completed_candidates'])?></strong><span>Based on participant status</span></article><article class="pm-suite-kpi"><small>Recorded outcomes</small><strong><?=number_format($stats['records'])?></strong><span>Achievement and impact records</span></article><article class="pm-suite-kpi"><small>Verified employment</small><strong><?=number_format($stats['employment']+$stats['placements'])?></strong><span>Verified entries plus active/completed placements</span></article></section>
<div class="pm-suite-grid"><section class="pm-suite-panel"><div class="pm-suite-panel-head"><h2>Record a programme outcome</h2><p>Use verified status only when a supporting source or reference is available.</p></div><form class="pm-suite-form" method="post"><?=csrf_field()?><div class="pm-suite-field"><label>Programme</label><select name="programme_id" id="outcomeProgramme" required><option value="">Select programme</option><?php foreach($programmes as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach;?></select></div><div class="pm-suite-field"><label>Cohort (optional)</label><select name="cohort_id" id="outcomeCohort"><option value="0">Programme-wide</option><?php foreach($cohorts as $c):?><option value="<?=$c['id']?>" data-programme="<?=$c['programme_id']?>"><?=e($c['programme_name'].' — '.$c['name'])?></option><?php endforeach;?></select></div><div class="pm-suite-field"><label>Candidate (optional)</label><select name="candidate_id" id="outcomeCandidate"><option value="0">Programme-level outcome</option><?php foreach($candidates as $c):?><option value="<?=$c['id']?>" data-programme="<?=$c['programme_id']?>" data-cohort="<?=$c['cohort_id']?>"><?=e($c['name'].' — '.$c['programme_name'].' / '.$c['cohort_name'])?></option><?php endforeach;?></select></div><div class="pm-suite-field"><label>Outcome type</label><select name="outcome_type" id="outcomeType"><?php foreach($types as $k=>$v):?><option value="<?=e($k)?>"><?=e($v)?></option><?php endforeach;?></select></div><div class="pm-suite-field"><label>Outcome title</label><input name="outcome_title" maxlength="180" required placeholder="e.g. Completed accredited training"></div><div class="pm-suite-field"><label>Details / evidence summary</label><textarea name="details" rows="3" maxlength="5000"></textarea></div><div class="pm-suite-field"><label>Date achieved</label><input type="date" name="achieved_on" required value="<?=date('Y-m-d')?>"></div><div class="pm-suite-field"><label>Verification reference</label><input name="verification_reference" maxlength="180" placeholder="Certificate, employer confirmation, evidence ID"></div><label style="display:flex;gap:.55rem;align-items:center;font-size:.8rem;font-weight:700"><input type="checkbox" name="verified" value="1" style="width:auto"> Evidence has been verified</label><button class="pm-suite-btn" type="submit" <?=$tableReady?'':'disabled'?>>Save outcome</button></form></section>
<section class="pm-suite-panel"><div class="pm-suite-panel-head"><h2>Recorded outcomes</h2><p><?=count($outcomes)?> outcome records across your assigned programmes.</p></div><div class="pm-suite-table-wrap"><table class="pm-suite-table"><thead><tr><th>Outcome</th><th>Candidate</th><th>Programme / cohort</th><th>Date</th><th>Verification</th></tr></thead><tbody><?php if(!$outcomes):?><tr><td colspan="5" class="pm-suite-empty">No outcome records yet. Add the first record using the form.</td></tr><?php else:foreach($outcomes as $o):?><tr><td><strong><?=e($o['outcome_title'])?></strong><span class="pm-suite-muted"><?=e($types[$o['outcome_type']]??ucfirst($o['outcome_type']))?><?=!empty($o['details'])?' · '.e(mb_strimwidth($o['details'],0,110,'…')):''?></span></td><td><?=e(trim($o['candidate_name']??'')?:'Programme-level')?></td><td><?=e($o['programme_name'])?><span class="pm-suite-muted"><?=e($o['cohort_name']??'Programme-wide')?></span></td><td><?=e(date('d M Y',strtotime($o['achieved_on'])))?></td><td><?php if((int)$o['verified']):?><span class="pm-suite-pill good">Verified</span><span class="pm-suite-muted"><?=e($o['verification_reference']??'Reference not provided')?></span><?php else:?><span class="pm-suite-pill warn">Unverified</span><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div><div class="pm-suite-notice" style="margin:1rem">Employment outcomes are shown as verified only when the outcome record is marked verified. Existing placement counts are sourced from the placements table and are shown separately from manually recorded outcomes.</div></section></div>
<script>(function(){var p=document.getElementById('outcomeProgramme'),c=document.getElementById('outcomeCohort'),u=document.getElementById('outcomeCandidate');function f(){Array.from(c.options).forEach(function(o){if(!o.value)return;o.hidden=!!p.value&&o.dataset.programme!==p.value;if(o.hidden&&o.selected)c.value='0'});Array.from(u.options).forEach(function(o){if(!o.value)return;var show=(!p.value||o.dataset.programme===p.value)&&(!c.value||c.value==='0'||o.dataset.cohort===c.value);o.hidden=!show;if(!show&&o.selected)u.value='0'});}p.addEventListener('change',f);c.addEventListener('change',f);f();})();</script>
</div></main></div><script src="<?=url('js/programme_manager_enhancements.js')?>?v=20261026"></script><script src="<?=url('js/original_pm_sidebar.js')?>?v=20261026"></script></body></html>
